code.en:
.toolbar {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}
.toolbar__nav {
  flex: 1 1 auto;
  min-width: 0; /* allow shrink below content min */
  overflow: auto;
}
.toolbar__actions {
  margin-inline-start: auto;
  flex: 0 0 auto;
}

