code.en:
/* Dashboard cell: Grid owns the page, Flex owns the panel. */
.main {
  grid-area: main;
  min-height: 0; /* track must shrink */
  display: flex;
  flex-direction: column;
}
.main__scroll {
  flex: 1 1 auto;
  min-height: 0; /* flex child must shrink or the page scrolls */
  overflow: auto;
}

code.vi:
/* Cell dashboard: Grid sở hữu page, Flex sở hữu panel. */
.main {
  grid-area: main;
  min-height: 0; /* track phải shrink */
  display: flex;
  flex-direction: column;
}
.main__scroll {
  flex: 1 1 auto;
  min-height: 0; /* flex child phải shrink, không thì page scroll */
  overflow: auto;
}

code.en:
:root {
  --space-2: 0.5rem;
  --space-4: 1rem;
  --text-body: clamp(1rem, 0.85rem + 0.6cqi, 1.125rem);
}
.card-grid {
  container-type: inline-size;
  display: grid;
  gap: var(--space-4);
  grid-template-columns: 1fr;
}
@container (min-width: 36rem) {
  .card-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
.hero-img {
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 9;
}
.shell {
  min-height: 100dvh;
}

