code.en:
@layer reset, tokens, components, utilities;

.card-grid {
  display: grid;
  grid-template-columns: 12rem 1fr;
}
.card {
  display: grid;
  grid-template-columns: subgrid;
  grid-column: span 2; /* must span the parent tracks */
}
.card:has(.error) {
  outline: 1px solid var(--color-danger);
}

